export const useRecordFromLocation = ({
    searchSource,
    stateSource,
}: UseRecordFromLocationOptions = {}): Partial<RaRecord> | null => {
    const location = useLocation();

    return useMemo(
        () => getRecordFromLocation(location, { searchSource, stateSource }),
        [location, searchSource, stateSource]
    );
