import { useMemo } from 'react';
import { parse } from 'query-string';
import { Location, useLocation } from 'react-router-dom';

import { RaRecord } from '../types';

export interface UseRecordFromLocationOptions {
    searchSource?: string;
    stateSource?: string;
}

/**
 * Get a record from the current location, whether it comes from the location
 * state or is serialized in the url search part.
 *
 * The record is extracted from:
 * - `location.state['record']` (or `options.stateSource` if provided)
 * - a stringified JSON object in the url search part under the `source` key
 *   (or `options.searchSource` if provided)
 *
 * When both the location state and the location search contain a record, the
 * one from the location state takes precedence.
 *
 * @example // location.state
 * getRecordFromLocation({ ...location, state: { record: { foo: 'bar' } } });
 * // { foo: 'bar' }
 *
 * @example // location.search
 * getRecordFromLocation({ ...location, search: '?source={"foo":"baz"}' });
 * // { foo: 'baz' }
 */
export const getRecordFromLocation = (
    { state, search }: Location,
    {
        searchSource = 'source',
        stateSource = 'record',
    }: UseRecordFromLocationOptions = {}
): Partial<RaRecord> | null => {
    let stateRecord: Partial<RaRecord> | null = null;
    if (state && (state as StateWithRecord)[stateSource]) {
        stateRecord = (state as StateWithRecord)[stateSource] ?? null;
    }

    let searchRecord: Partial<RaRecord> | null = null;
    if (search) {
        try {
            const searchParams = parse(search);
            const source = searchParams[searchSource];
            if (source) {
                if (Array.isArray(source)) {
                    console.error(
                        `Failed to parse location search parameter '${search}'. To pre-fill some fields in the form, pass a stringified ${searchSource} parameter (e.g. '?${searchSource}={"title":"foo"}')`
                    );
                } else {
                    searchRecord = JSON.parse(source);
                }
            }
        } catch (e) {
            console.error(
                `Failed to parse location search parameter '${search}'. To pre-fill some fields in the form, pass a stringified ${searchSource} parameter (e.g. '?${searchSource}={"title":"foo"}')`
            );
        }
    }

    // When both the location state and the location search contain a record,
    // the one from the location state takes precedence.
    if (stateRecord && searchRecord) {
        return stateRecord;
    }

    return searchRecord ?? stateRecord ?? null;
};

