ex;\n    flex-direction: column;\n    justify-content: center;\n    border-radius: 3px;\n}\n.browser-bar .button:hover {\n    background-color: #aaa;\n}\n.browser-bar svg {\n    height: 16px;\n    width: 16px;\n}\n\n.browser-bar form {\n    background-color: white;\n    color: #bbb;\n    border-radius: 3px;\n    border-width: 1px;\n    border-style: solid;\n    border-color: #d7d3d3;\n    font-size: 10px;\n    flex-grow: 1;\n    display: flex;\n    flex-direction: column;\n}\n.browser-bar input {\n    border: none;\n    border-radius: 3px;\n    padding: 3px 7px 4px;\n}\n\n.browser-container {\n    background-color: #fff;\n    height: 350px;\n    border-left: 1px solid #ccc;\n    border-right: 1px solid #ccc;\n    border-bottom: 1px solid #ccc;\n    border-bottom-left-radius: 3px;\n    border-bottom-right-radius: 3px;\n}\n`;\n\nconst BackwardIcon = () => (\n    <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        fill=\"none\"\n        viewBox=\"0 0 24 24\"\n        stroke=\"currentColor\"\n    >\n        <path\n            strokeLinecap=\"round\"\n            strokeLinejoin=\"round\"\n            strokeWidth={2}\n            d=\"M15 19l-7-7 7-7\"\n        />\n    </svg>\n);\n\nconst ForwardIcon = () => (\n    <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        fill=\"none\"\n        viewBox=\"0 0 24 24\"\n        stroke=\"currentColor\"\n    >\n        <path\n            strokeLinecap=\"round\"\n            strokeLinejoin=\"round\"\n            strokeWidth={2}\n            d=\"M9 5l7 7-7 7\"\n        />\n    </svg>\n);\n\nconst RefreshIcon = () => (\n    <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        fill=\"none\"\n        viewBox=\"0 0 24 24\"\n        stroke=\"currentColor\"\n    >\n        <path\n            strokeLinecap=\"round\"\n            strokeLinejoin=\"round\"\n            strokeWidth={2}\n            d=\"M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15\"\n        />\n