AAtB,CAAsB,EACxC,MAAM,EAAE,aAAa,EACrB,aAAa,EAAE,aAAa;gBAE5B,oBAAC,mBAAmB,OAAG;gBACvB,6BAAK,KAAK,EAAE,EAAE,OAAO,EAAE,MAAM,EAAE,GAAG,EAAE,KAAK,EAAE,MAAM,EAAE,KAAK,EAAE;oBACtD,oBAAC,uBAAI,IAAC,EAAE,EAAC,UAAU,cAAe;oBAClC,oBAAC,uBAAI,IAAC,EAAE,EAAC,WAAW,eAAgB,CAClC;gBACN,oBAAC,yBAAM;oBACH,oBAAC,wBAAK,IACF,IAAI,EAAC,UAAU,EACf,OAAO,EACH;4BACI,oBAAC,KAAK,IAAC,GAAG,EAAC,OAAO,EAAC,MAAM,EAAC,OAAO,GAAG;4BACpC,oBAAC,KAAK,IAAC,GAAG,EAAC,UAAU,EAAC,MAAM,EAAC,UAAU,GAAG,CAC3C,GAET;oBACF,oBAAC,wBAAK,IACF,IAAI,EAAC,WAAW,EAChB,OAAO,EAAE,oBAAC,KAAK,IAAC,GAAG,EAAC,MAAM,EAAC,MAAM,EAAC,MAAM,GAAG,GAC7C,CACG;gBACT,oBAAC,YAAY,OAAG;gBAChB,iCAAM,IAAI,CAAC,SAAS,CAAC,aAAa,EAAE,IAAI,EAAE,CAAC,CAAC,CAAO,CAChD,CACQ,CACJ,CACtB,CAAC;AACN,CAAC,CAAC;AAjDW,QAAA,eAAe,mBAiD1B;AAEF,IAAM,aAAa,GAAG;IACV,IAAA,aAAa,GAAK,IAAA,0BAAsB,GAAE,cAA7B,CAA8B;IACnD,OAAO,CACH,gCACK,aAAa,CAAC,GAAG,CAAC,UAAC,EAAW,EAAE,EAAE;YAAb,OAAO,aAAA;QAAW,OAAA,CACpC,4BAAI,GAAG,EAAE,EAAE,IAAG,OAAO,CAAM,CAC9B;IAFuC,CAEvC,CAAC,CACD,CACR,CAAC;AACN,CAAC,CAAC;AAEK,IAAM,oBAAoB,GAAG;IAChC,IAAM,IAAI,GAAG,KAAK,CAAC,WAAW,CAAC,UAAA,MAAM;QACjC,IAAM,MAAM,GAAQ,EAAE,CAAC;QACvB,IAAI,CAAC,MAAM,CAAC,cAAc,EAAE;YACxB,MAAM,CAAC,cAAc,GAAG,wBAAwB,CAAC;SACpD;QACD,IAAI,CAAC,MAAM,CAAC,aAAa,EAAE;YACvB,MAAM,CAAC,aAAa,GAAG,wBAAwB,CAAC;SACnD;QACD,IAAI,CAAC,MAAM,CAAC,2BAA2B,EAAE;YACrC,MAAM,CAAC,2BAA2B,GAAG,yBAAyB,CAAC;SAClE;QACD,IAAI,CAAC,MAAM,CAAC,kCAAkC,EAAE;YAC5C,MAAM,CAAC,kCAAkC;gBACrC,wBAAwB,CAAC;SAChC;QACD,IAAI,CAAC,MAAM,CAAC,mBAAmB,EAAE;YAC7B,MAAM,CAAC,mBAAmB,GAAG,wBAAwB,CAAC;YACtD,MAAM,CAAC,IAAI,GAAG;gBACV,WAAW,EAAE,+CAA+C;aAC/D,CAAC;SACL;QACD,OAAO,MAAM,CAAC,IAAI,CAAC,MAAM,CAAC,CAAC,MAAM,GAAG,CAAC,CAAC,CAAC,CAAC,MAAM,CAAC,CAAC,CAAC,SAAS,CAAC;IAC/D,CAAC,EAAE,EAAE,CAAC,CAAC;IACP,OAAO,CACH,oBAAC,uBAAgB,IAAC,YAAY,EAAE,mBAAmB;QAC/C,oBAAC,uBAAmB,IAAC,KAAK,EAAE,EAAE,IAAI,MAAA,EAAE;YAChC,oBAAC,WAAI,IACD,MAAM,EAAE;oBACJ,EAAE,EAAE,CAAC;oBACL,cAAc,EAAE,KAAK;oBACrB,aAAa,EAAE,KAAK;oBACpB,2BAA2B,EAAE,KAAK;oBAClC,kCAAkC,EAAE,KAAK;oBACzC,mBAAmB,EAAE,KAAK;iBAC7B;gBAED,oBAAC,KAAK,IAAC,MAAM,EAAC,gBAAgB,GAAG;gBACjC,oBAAC,KAAK,IAAC,MAAM,EAAC,eAAe,GAAG;gBAChC,oBAAC,KAAK,IAAC,MAAM,EAAC,6BAA6B,GAAG;gBAC9C,oBAAC,KAAK,IAAC,MAAM,EAAC,oCAAoC,GAAG;gBACrD,oBAAC,KAAK,IAAC,MAAM,EAAC,qBAAqB,GAAG;gBACtC,gCAAQ,IAAI,EAAC,QAAQ,aAAgB,CAClC;YACP,oBAAC,aAAa,OAAG,CACC,CACP,CACtB,CAAC;AACN,CAAC,CAAC;AAhDW,QAAA,oBAAoB,wBAgD/B","names":[],"sources":["/workspace/repo/packages/ra-core/src/form/Form.stories.tsx"],"sourcesContent":["import * as React from 'react';\nimport {\n    useController,\n    UseControllerProps,\n    useFormContext,\n    useFormState,\n} from 'react-hook-form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport * as z from 'zod';\nimport polyglotI18nProvider from 'ra-i18n-polyglot';\nimport englishMessages from 'ra-language-english';\nimport { Route, Routes, useNavigate, Link, HashRouter } from 'react-router-dom';\n\nimport { CoreAdminContext } from '../core';\nimport { TestMemoryRouter } from '../routing';\nimport { RaRecord } from '../types';\nimport { Form } from './Form';\nimport { useInput } from './useInput';\nimport { useRecordFromLocation } from './useRecordFromLocation';\nimport { required, ValidationError } from './validation';\nimport { mergeTranslations } from '../i18n';\nimport { I18nProvider } from '../types';\nimport { SaveContextProvider, useNotificationContext } from '..';\n\nexport default {\n    title: 'ra-core/form/Form',\n};\n\nconst Input = props => {\n    const { field, fieldState } = useInput(props);\n    return (\n        <div\n            style={{\n                display: 'flex',\n                gap: '1em',\n                margin: '1em',\n                alignItems: 'center',\n            }}\n        >\n            <label htmlFor={field.name}>{field.name}</label>\n            <input\n                aria-label={field.name}\n                id={field.name}\n                type=\"text\"\n                aria-invalid={fieldState.invalid}\n                {...field}\n            />\n            {fieldState.error && fieldState.error.message ? (\n                <ValidationError error={fieldState.error.message} />\n            ) : null}\n        </div>\n    );\n};\n\nconst SubmitButton = () => {\n    const state = useFormState();\n\n    return (\n        <button type=\"submit\" disabled={!state.isDirty}>\n            Submit\n        </button>\n    );\n};\n\nexport const Basic = () => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n            >\n                <Input source=\"field1\" />\n                <Input source=\"field2\" defaultValue=\"bar\" />\n                <Input source=\"field3\" defaultValue=\"\" />\n                <Input source=\"field4\" />\n                <Input source=\"field5\" parse={v => v || undefined} />\n                <Input source=\"field6\" />\n                <SubmitButton />\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst CustomInput = (props: UseControllerProps) => {\n    const { field, fieldState } = useController(props);\n    return (\n        <div\n            style={{\n                display: 'flex',\n                gap: '1em',\n                margin: '1em',\n                alignItems: 'center',\n            }}\n        >\n            <label htmlFor={field.name}>{field.name}</label>\n            <input\n                aria-label={field.name}\n                id={field.name}\n                type=\"text\"\n                aria-invalid={fieldState.invalid}\n                {...field}\n                value={field.value ?? ''}\n            />\n            <p>{fieldState.error?.message}</p>\n        </div>\n    );\n};\n\nexport const SanitizeEmptyValues = () => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    const field11 = { name: 'field11' };\n    const field12 = {\n        name: 'field12',\n        defaultValue: 'bar',\n    };\n    const field13 = {\n        name: 'field13',\n        defaultValue: '',\n    };\n    const field14 = { name: 'field14' };\n    const field16 = { name: 'field16' };\n    return (\n        <CoreAdminContext>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{\n                    id: 1,\n                    field1: 'bar',\n                    field6: null,\n                    field11: 'bar',\n                    field16: null,\n                }}\n                sanitizeEmptyValues\n            >\n                <Input source=\"field1\" />\n                <Input source=\"field2\" defaultValue=\"bar\" />\n                <Input source=\"field3\" defaultValue=\"\" />\n                <Input source=\"field4\" />\n                <Input source=\"field5\" parse={v => v || undefined} />\n                <Input source=\"field6\" />\n                <CustomInput {...field11} />\n                <CustomInput {...field12} />\n                <CustomInput {...field13} />\n                <CustomInput {...field14} />\n                <CustomInput {...field16} />\n\n                <SubmitButton />\n            </Form>\n            <pre data-testid=\"result\">\n                {JSON.stringify(submittedData, null, 2)}\n            </pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const NullValue = () => {\n    const [result, setResult] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form record={{ foo: null }} onSubmit={data => setResult(data)}>\n                <Input source=\"foo\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(result, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const UndefinedValue = () => {\n    const [result, setResult] = React.useState<any>();\n    return (\n        <CoreAdminContext>\n            <Form record={{}} onSubmit={data => setResult(data)}>\n                <Input source=\"foo\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(result, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst defaultI18nProvider = polyglotI18nProvider(() =>\n    mergeTranslations(englishMessages, {\n        app: {\n            validation: {\n                required: 'This field must be provided',\n            },\n        },\n    })\n);\n\nexport const FormLevelValidation = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n                validate={(values: any) => {\n                    const errors: any = {};\n                    if (!values.defaultMessage) {\n                        errors.defaultMessage = 'ra.validation.required';\n                    }\n                    if (!values.customMessage) {\n                        errors.customMessage = 'This field is required';\n                    }\n                    if (!values.customMessageTranslationKey) {\n                        errors.customMessageTranslationKey =\n                            'app.validation.required';\n                    }\n                    if (!values.missingCustomMessageTranslationKey) {\n                        errors.missingCustomMessageTranslationKey =\n                            'app.validation.missing';\n                    }\n                    return errors;\n                }}\n            >\n                <Input source=\"defaultMessage\" />\n                <Input source=\"customMessage\" />\n                <Input source=\"customMessageTranslationKey\" />\n                <Input source=\"missingCustomMessageTranslationKey\" />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nexport const InputLevelValidation = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    const [submittedData, setSubmittedData] = React.useState<any>();\n    return (\n        <CoreAdminContext i18nProvider={i18nProvider}>\n            <Form\n                onSubmit={data => setSubmittedData(data)}\n                record={{ id: 1, field1: 'bar', field6: null }}\n            >\n                <Input source=\"defaultMessage\" validate={required()} />\n                <Input\n                    source=\"customMessage\"\n                    validate={required('This field is required')}\n                />\n                <Input\n                    source=\"customMessageTranslationKey\"\n                    validate={required('app.validation.required')}\n                />\n                <Input\n                    source=\"missingCustomMessageTranslationKey\"\n                    validate={required('app.validation.missing')}\n                />\n                <button type=\"submit\">Submit</button>\n            </Form>\n            <pre>{JSON.stringify(submittedData, null, 2)}</pre>\n        </CoreAdminContext>\n    );\n};\n\nconst zodSchema = z.object({\n    defaultMessage: z.string(), //.min(1),\n    customMessage: z.string({\n        required_error: 'This field is required',\n    }),\n    customMessageTranslationKey: z.string({\n        required_error: 'app.validation.required',\n    }),\n    missingCustomMessageTranslationKey: z.string({\n        required_error: 'app.validation.missing',\n    }),\n});\n\nexport const ZodResolver = ({\n    i18nProvider = defaultI18nProvider,\n}: {\n    i18nProvider?: I18nProvider;\n}) => {\n    c