I,CAAC,KAAK,CAAC;QACxB,KAAK,CAAC,KAAK,GAAG,IAAI,CAAC,KAAK,CAAC;KAC5B;IACD,IAAI,KAAK,CAAC,OAAO,IAAI,IAAI,EAAE;QACvB,KAAK,CAAC,OAAO,GAAG,OAAO,CAAC;KAC3B;IACD,IAAI,KAAK,CAAC,IAAI,IAAI,IAAI,EAAE;QACpB,KAAK,CAAC,IAAI,GAAG,CAAC,CAAC;KAClB;IAED,OAAO,sBACA,KAAK,KACR,IAAI,EAAE,IAAA,0BAAkB,EAAC,KAAK,CAAC,IAAI,EAAE,CAAC,CAAC,EACvC,OAAO,EAAE,IAAA,0BAAkB,EAAC,KAAK,CAAC,OAAO,EAAE,EAAE,CAAC,GACnC,CAAC;AACpB,CAAC,CAAC;AA9BW,QAAA,QAAQ,YA8BnB;AAEK,IAAM,kBAAkB,GAAG,UAC9B,cAA2C,EAC3C,YAAoB;IAEpB,IAAI,OAAO,cAAc,KAAK,WAAW,EAAE;QACvC,OAAO,YAAY,CAAC;KACvB;IACD,IAAM,YAAY,GACd,OAAO,cAAc,KAAK,QAAQ;QAC9B,CAAC,CAAC,QAAQ,CAAC,cAAc,EAAE,EAAE,CAAC;QAC9B,CAAC,CAAC,cAAc,CAAC;IAEzB,OAAO,KAAK,CAAC,YAAY,CAAC,CAAC,CAAC,CAAC,YAAY,CAAC,CAAC,CAAC,YAAY,CAAC;AAC7D,CAAC,CAAC;AAbW,QAAA,kBAAkB,sBAa7B;AAqCF,IAAM,WAAW,GAAG,EAAE,CAAC;AAEvB,IAAM,WAAW,GAAG;IAChB,KAAK,EAAE,IAAI;IACX,KAAK,EAAE,uBAAQ;CACT,CAAC;AAEX,IAAM,aAAa,GAAG,EAAE,CAAC","names":[],"sources":["/workspace/repo/packages/ra-core/src/controller/list/useListParams.ts"],"sourcesContent":["import { useCallback, useMemo, useEffect, useState, useRef } from 'react';\nimport { parse, stringify } from 'query-string';\nimport lodashDebounce from 'lodash/debounce';\nimport { useNavigate, useLocation } from 'react-router-dom';\n\nimport { useStore } from '../../store';\nimport queryReducer, {\n    SET_FILTER,\n    HIDE_FILTER,\n    SHOW_FILTER,\n    SET_PAGE,\n    SET_PER_PAGE,\n    SET_SORT,\n    SORT_ASC,\n} from './queryReducer';\nimport { SortPayload, FilterPayload } from '../../types';\nimport removeEmpty from '../../util/removeEmpty';\nimport { useIsMounted } from '../../util/hooks';\n\nexport interface ListParams {\n    sort: string;\n    order: 'ASC' | 'DESC';\n    page: number;\n    perPage: number;\n    filter: any;\n    displayedFilters: any;\n}\n\n/**\n * Get the list parameters (page, sort, filters) and modifiers.\n *\n * These parameters are merged from 3 sources:\n *   - the query string from the URL\n *   - the params stored in the state (from previous navigation)\n *   - the options passed to the hook (including the filter defaultValues)\n *\n * @returns {Array} A tuple [parameters, modifiers].\n * Destructure as [\n *    { page, perPage, sort, order, filter, filterValues, displayedFilters, requestSignature },\n *    { setFilters, hideFilter, showFilter, setPage, setPerPage, setSort }\n * ]\n *\n * @example\n *\n * const [listParams, listParamsActions] = useListParams({\n *      resource: 'posts',\n *      location: location // From react-router. Injected to your component by react-admin inside a List\n *      filterDefaultValues: {\n *          published: true\n *      },\n *      sort: {\n *          field: 'published_at',\n *          order: 'DESC'\n *      },\n *      perPage: 25\n * });\n *\n * const {\n *      page,\n *      perPage,\n *      sort,\n *      order,\n *      filter,\n *      filterValues,\n *      displayedFilters,\n *      requestSignature\n * } = listParams;\n *\n * const {\n *      setFilters,\n *      hideFilter,\n *      showFilter,\n *      setPage,\n *      setPerPage,\n *      setSort,\n * } = listParamsActions;\n */\nexport const useListParams = ({\n    debounce = 500,\n    disableSyncWithLocation = false,\n    filterDefaultValues,\n    perPage = 10,\n    resource,\n    sort = defaultSort,\n    storeKey = disableSyncWithLocation ? false : `${resource}.listParams`,\n}: ListParamsOptions): [Parameters, Modifiers] => {\n    const location = useLocation();\n    const navigate = useNavigate();\n    const [localParams, setLocalParams] = useState(defaultParams);\n    // As we can't conditionally call a hook, if the storeKey is false,\n    // we'll ignore the params variable later on and won't call setParams either.\n    const [params, setParams] = useStore(\n        storeKey || `${resource}.listParams`,\n        defaultParams\n    );\n    const tempParams = useRef<ListParams>();\n    const isMounted = useIsMounted();\n\n    const requestSignature = [\n        location.search,\n        resource,\n        storeKey,\n        JSON.stringify(!storeKey ? localParams : params),\n        JSON.stringify(filterDefaultValues),\n        JSON.stringify(sort),\n        perPage,\n        disableSyncWithLocation,\n    ];\n\n    const queryFromLocation = disableSyncWithLocation\n        ? {}\n        : parseQueryFromLocation(location);\n\n    const query = useMemo(\n        () =>\n            getQuery({\n                queryFromLocation,\n                params: !storeKey ? localParams : params,\n                filterDefaultValues,\n                sort,\n                perPage,\n            }),\n        requestSignature // eslint-disable-line react-hooks/exhaustive-deps\n    );\n\n    // if the location includes params (for example from a link like\n    // the categories products on the demo), we need to persist them in the\n    // store as well so that we don't lose them after a redirection back\n    // to the list\n    useEffect(() => {\n        if (Object.keys(queryFromLocation).length > 0) {\n            setParams(query);\n        }\n    }, [location.search]); // eslint-disable-line\n\n    const changeParams = useCallback(\n        action => {\n            // do not change params if the component is already unmounted\n            // this is necessary because changeParams can be debounced, and therefore\n            // executed after the component is unmounted\n            if (!isMounted.current) return;\n\n            if (!tempParams.current) {\n                // no other changeParams action dispatched this tick\n                tempParams.current = queryReducer(query, action);\n                // schedule side effects for next tick\n                setTimeout(() => {\n                    if (!tempParams.current) {\n                        // the side effects were already processed by another changeParams\n                        return;\n                    }\n                    if (disableSyncWithLocation && !storeKey) {\n                        setLocalParams(tempParams.current);\n                    } else if (disableSyncWithLocation && !!storeKey) {\n                        setParams(tempParams.current);\n                    } else {\n                        // the useEffect above will apply the changes to the params in the store\n                        navigate(\n                            {\n                                search: `?${stringify({\n                                    ...tempParams.current,\n                                    filter: JSON.stringify(\n                                        tempParams.current.filter\n                                    ),\n                                    displayedFilters: JSON.stringify(\n                                        tempParams.current.displayedFilters\n                                    ),\n                                })}`,\n                            },\n                            {\n                                state: {\n                                    _scrollToTop: action.type === SET_PAGE,\n                                },\n                            }\n                        );\n                    }\n                    tempParams.current = undefined;\n                }, 0);\n            } else {\n                // side effects already scheduled, just change the params\n                tempParams.current = queryReducer(tempParams.current, action);\n            }\n        },\n        [...requestSignature, navigate] // eslint-disable-line react-hooks/exhaustive-deps\n    );\n\n    const setSort = useCallback(\n        (sort: SortPayload) =>\n            changeParams({\n                type: SET_SORT,\n                payload: sort,\n            }),\n        [changeParams]\n    );\n\n    const setPage = useCallback(\n        (newPage: number) => changeParams({ type: SET_PAGE, payload: newPage }),\n        [changeParams]\n    );\n\n    const setPerPage = useCallback(\n        (newPerPage: number) =>\n            changePa